// Vercel sends an event envelope:
//   { id, type, createdAt, payload: { deployment, target, ... }, ... }
// Common types we care about:
//   deployment.created
//   deployment.succeeded
//   deployment.error
//   deployment.canceled
// Other events (project.created, etc.) are filtered to a quiet branch.

const fs = require('fs');
const path = require('path');

const input = $input.first().json || {};
const body = input.body && typeof input.body === 'object' ? input.body : input;
const type = body.type || '(unknown)';
const deployment = (body.payload && body.payload.deployment) || {};
const target = (body.payload && body.payload.target) || deployment.target || null;
const meta = deployment.meta || {};

const commitSha = meta.githubCommitSha || meta.gitlabCommitSha || meta.bitbucketCommitSha || null;
const commitMsg = meta.githubCommitMessage || meta.gitlabCommitMessage || meta.bitbucketCommitMessage || null;
const commitAuthor = meta.githubCommitAuthorName || meta.gitlabCommitAuthorName || meta.bitbucketCommitAuthorName || null;
const url = deployment.url ? `https://${deployment.url}` : null;
const name = deployment.name || 'kingdom-pwa-node';

// Also persist the event for later inspection.
const LOG_DIR = '/data/chatin/_vercel';
try { fs.mkdirSync(LOG_DIR, { recursive: true }); } catch(_) {}
try {
  const ts = new Date().toISOString().replace(/[:.]/g, '-');
  fs.writeFileSync(path.join(LOG_DIR, `${ts}__${type.replace(/[^a-zA-Z0-9_.-]/g, '_')}.json`), JSON.stringify(body, null, 2));
} catch(_) {}

let shouldPost = true;
let emoji = '⚙️';
let headline = type;

switch (type) {
  case 'deployment.created':
    emoji = '🟡';
    headline = `Building${target ? ' (' + target + ')' : ''}`;
    break;
  case 'deployment.succeeded':
  case 'deployment.ready':
    emoji = '🟢';
    headline = `Live${target ? ' (' + target + ')' : ''}`;
    break;
  case 'deployment.error':
    emoji = '🔴';
    headline = `Build failed${target ? ' (' + target + ')' : ''}`;
    break;
  case 'deployment.canceled':
    emoji = '⚪';
    headline = `Deploy canceled${target ? ' (' + target + ')' : ''}`;
    break;
  default:
    shouldPost = false;
}

const lines = [`${emoji} *${headline}* — ${name}`];
if (commitMsg) lines.push(`> ${String(commitMsg).split('\n')[0].slice(0, 180)}`);
if (commitSha) lines.push(`commit: \`${String(commitSha).slice(0, 7)}\`${commitAuthor ? ` · ${commitAuthor}` : ''}`);
if (url) lines.push(url);

const chatText = lines.join('\n');

return [{
  json: {
    should_post: shouldPost,
    chat_text: chatText,
    type,
    target,
    url
  }
}];
